7|// Fuzzer inspired by /src/jq_test.c
8|// The goal is to have the fuzzer execute the functions:
9|// jq_compile -> jv_parse -> jq_next.
10|extern "C" int LLVMFuzzerTestOneInput(uint8_t *data, size_t size) {
11|  FuzzedDataProvider fdp(data, size);
12|  std::string prog_payload = fdp.ConsumeRandomLengthString();
13|  std::string parse_payload1 = fdp.ConsumeRandomLengthString();
14|  std::string parse_payload2 = fdp.ConsumeRandomLengthString();
15|
16|  jq_state *jq = NULL;
17|  jq = jq_init();
18|  if (jq != NULL) {
19|    jq_set_attr(jq, jv_string("JQ_ORIGIN"), jv_string("/tmp/"));
20|
21|    if (jq_compile(jq, prog_payload.c_str())) {
22|      // Process to jv_parse and then jv_next
23|      jv input = jv_parse(parse_payload1.c_str());
24|      if (jv_is_valid(input)) {
25|        jq_start(jq, input, 0);
26|        jv next = jv_parse(parse_payload2.c_str());
27|        if (jv_is_valid(next)) {
28|          jv actual = jq_next(jq);
29|          jv_free(actual);
30|        }
31|        jv_free(next);
32|      } else {
33|        // Only free if input is invalid as otherwise jq_teardown
34|        // frees it.
35|        jv_free(input);
36|      }
37|    }
38|  }
39|  jq_teardown(&jq);
40|
41|  return 0;
42|}

