1109|void jq_start(jq_state *jq, jv input, int flags) {
1110|  jv_nomem_handler(jq->nomem_handler, jq->nomem_handler_data);
1111|  jq_reset(jq);
1112|
1113|  struct closure top = {jq->bc, -1};
1114|  struct frame* top_frame = frame_push(jq, top, 0, 0);
1115|  top_frame->retdata = 0;
1116|  top_frame->retaddr = 0;
1117|
1118|  stack_push(jq, input);
1119|  stack_save(jq, jq->bc->code, stack_get_pos(jq));
1120|  jq->debug_trace_enabled = flags & JQ_DEBUG_TRACE_ALL;
1121|  jq->initial_execution = 1;
