343|jv jq_next(jq_state *jq) {
344|  jv_nomem_handler(jq->nomem_handler, jq->nomem_handler_data);
345|
346|  uint16_t* pc = stack_restore(jq);
347|  assert(pc);
348|
349|  int raising;
350|  int backtracking = !jq->initial_execution;
351|
352|  jq->initial_execution = 0;
353|  assert(jv_get_kind(jq->error) == JV_KIND_NULL);
354|  while (1) {
355|    if (jq->halted) {
356|      if (jq->debug_trace_enabled)
357|        printf("\t<halted>\n");
358|      return jv_invalid();
359|    }
360|    uint16_t opcode = *pc;
361|    raising = 0;
362|
363|    if (jq->debug_trace_enabled) {
364|      dump_operation(frame_current(jq)->bc, pc);
365|      printf("\t");
366|      const struct opcode_description* opdesc = opcode_describe(opcode);
367|      stack_ptr param = 0;
368|      if (!backtracking) {
369|        int stack_in = opdesc->stack_in;
370|        if (stack_in == -1) stack_in = pc[1];
371|        param = jq->stk_top;
372|        for (int i=0; i<stack_in; i++) {
373|          if (i != 0) {
374|            printf(" | ");
375|            param = *stack_block_next(&jq->stk, param);
376|          }
377|          if (!param) break;
378|          jv_dump(jv_copy(*(jv*)stack_block(&jq->stk, param)), JV_PRINT_REFCOUNT);
379|          //printf("<%d>", jv_get_refcnt(param->val));
380|          //printf(" -- ");
381|          //jv_dump(jv_copy(jq->path), 0);
382|        }
383|        if (jq->debug_trace_enabled & JQ_DEBUG_TRACE_DETAIL) {
384|          while ((param = *stack_block_next(&jq->stk, param))) {
385|            printf(" || ");
386|            jv_dump(jv_copy(*(jv*)stack_block(&jq->stk, param)), JV_PRINT_REFCOUNT);
387|          }
388|        }
389|      } else {
390|        printf("\t<backtracking>");
391|      }
392|
393|      printf("\n");
394|    }
395|
396|    if (backtracking) {
397|      opcode = ON_BACKTRACK(opcode);
398|      backtracking = 0;
399|      raising = !jv_is_valid(jq->error);
400|    }
401|    pc++;
402|
403|    switch (opcode) {
404|    default: assert(0 && "invalid instruction");
405|
406|    case TOP: break;
407|
408|    case ERRORK: {
409|      jv v = jv_array_get(jv_copy(frame_current(jq)->bc->constants), *pc++);
410|      set_error(jq, jv_invalid_with_msg(v));
411|      goto do_backtrack;
412|    }
413|
414|    case LOADK: {
415|      jv v = jv_array_get(jv_copy(frame_current(jq)->bc->constants), *pc++);
416|      assert(jv_is_valid(v));
417|      jv_free(stack_pop(jq));
418|      stack_push(jq, v);
419|      break;
420|    }
421|
422|    case GENLABEL: {
423|      stack_push(jq, JV_OBJECT(jv_string("__jq"), jv_number(jq->next_label++)));
424|      break;
425|    }
426|
427|    case DUP: {
428|      jv v = stack_pop(jq);
429|      stack_push(jq, jv_copy(v));
430|      stack_push(jq, v);
431|      break;
432|    }
433|
434|    case DUPN: {
435|      jv v = stack_popn(jq);
436|      stack_push(jq, jv_copy(v));
437|      stack_push(jq, v);
438|      break;
439|    }
440|
441|    case DUP2: {
442|      jv keep = stack_pop(jq);
443|      jv v = stack_pop(jq);
444|      stack_push(jq, jv_copy(v));
445|      stack_push(jq, keep);
446|      stack_push(jq, v);
447|      break;
448|    }
449|
450|    case SUBEXP_BEGIN: {
451|      jv v = stack_pop(jq);
452|      stack_push(jq, jv_copy(v));
453|      stack_push(jq, v);
454|      jq->subexp_nest++;
455|      break;
456|    }
457|
458|    case SUBEXP_END: {
459|      assert(jq->subexp_nest > 0);
460|      jq->subexp_nest--;
461|      jv a = stack_pop(jq);
462|      jv b = stack_pop(jq);
463|      stack_push(jq, a);
464|      stack_push(jq, b);
465|      break;
466|    }
467|
468|    case PUSHK_UNDER: {
469|      jv v = jv_array_get(jv_copy(frame_current(jq)->bc->constants), *pc++);
470|      assert(jv_is_valid(v));
471|      jv v2 = stack_pop(jq);
472|      stack_push(jq, v);
473|      stack_push(jq, v2);
474|      break;
475|    }
476|
477|    case POP: {
478|      jv_free(stack_pop(jq));
479|      break;
480|    }
481|
482|    case APPEND: {
483|      jv v = stack_pop(jq);
484|      uint16_t level = *pc++;
485|      uint16_t vidx = *pc++;
486|      jv* var = frame_local_var(jq, vidx, level);
487|      assert(jv_get_kind(*var) == JV_KIND_ARRAY);
488|      *var = jv_array_append(*var, v);
489|      break;
490|    }
491|
492|    case INSERT: {
493|      jv stktop = stack_pop(jq);
494|      jv v = stack_pop(jq);
495|      jv k = stack_pop(jq);
496|      jv objv = stack_pop(jq);
497|      assert(jv_get_kind(objv) == JV_KIND_OBJECT);
498|      if (jv_get_kind(k) == JV_KIND_STRING) {
499|        stack_push(jq, jv_object_set(objv, k, v));
500|        stack_push(jq, stktop);
501|      } else {
502|        char errbuf[15];
503|        set_error(jq, jv_invalid_with_msg(jv_string_fmt("Cannot use %s (%s) as object key",
504|                                                        jv_kind_name(jv_get_kind(k)),
505|                                                        jv_dump_string_trunc(jv_copy(k), errbuf, sizeof(errbuf)))));
506|        jv_free(stktop);
507|        jv_free(v);
508|        jv_free(k);
509|        jv_free(objv);
510|        goto do_backtrack;
511|      }
512|      break;
513|    }
514|
515|    case ON_BACKTRACK(RANGE):
516|    case RANGE: {
517|      uint16_t level = *pc++;
518|      uint16_t v = *pc++;
519|      jv* var = frame_local_var(jq, v, level);
520|      jv max = stack_pop(jq);
521|      if (raising) {
522|        jv_free(max);
523|        goto do_backtrack;
524|      } 
525|      if (jv_get_kind(*var) != JV_KIND_NUMBER ||
526|          jv_get_kind(max) != JV_KIND_NUMBER) {
527|        set_error(jq, jv_invalid_with_msg(jv_string_fmt("Range bounds must be numeric")));
528|        jv_free(max);
529|        goto do_backtrack;
530|      } else if (jv_number_value(*var) >= jv_number_value(max)) {
531|        /* finished iterating */
532|        jv_free(max);
533|        goto do_backtrack;
534|      } else {
535|        jv curr = *var;
536|        *var = jv_number(jv_number_value(*var) + 1);
537|
538|        struct stack_pos spos = stack_get_pos(jq);
539|        stack_push(jq, max);
540|        stack_save(jq, pc - 3, spos);
541|
542|        stack_push(jq, curr);
543|      }
544|      break;
545|    }
546|
547|      // FIXME: loadv/storev may do too much copying/freeing
548|    case LOADV: {
549|      uint16_t level = *pc++;
550|      uint16_t v = *pc++;
551|      jv* var = frame_local_var(jq, v, level);
552|      if (jq->debug_trace_enabled) {
553|        printf("V%d = ", v);
554|        jv_dump(jv_copy(*var), JV_PRINT_REFCOUNT);
555|        printf("\n");
556|      }
557|      jv_free(stack_pop(jq));
558|      stack_push(jq, jv_copy(*var));
559|      break;
560|    }
561|
562|      // Does a load but replaces the variable with null
563|    case LOADVN: {
564|      uint16_t level = *pc++;
565|      uint16_t v = *pc++;
566|      jv* var = frame_local_var(jq, v, level);
567|      if (jq->debug_trace_enabled) {
568|        printf("V%d = ", v);
569|        jv_dump(jv_copy(*var), JV_PRINT_REFCOUNT);
570|        printf("\n");
571|      }
572|      jv_free(stack_popn(jq));
573|
574|      // This `stack_push()` invalidates the `var` reference, so
575|      stack_push(jq, *var);
576|      // we have to re-resolve `var` before we can set it to null
