580|    }
581|
582|    case STOREVN:
583|        stack_save(jq, pc - 1, stack_get_pos(jq));
584|        JQ_FALLTHROUGH;
585|    case STOREV: {
586|      uint16_t level = *pc++;
587|      uint16_t v = *pc++;
588|      jv* var = frame_local_var(jq, v, level);
589|      jv val = stack_pop(jq);
590|      if (jq->debug_trace_enabled) {
591|        printf("V%d = ", v);
592|        jv_dump(jv_copy(val), 0);
593|        printf(" (%d)\n", jv_get_refcnt(val));
594|      }
595|      jv_free(*var);
596|      *var = val;
597|      break;
598|    }
599|
600|    case ON_BACKTRACK(STOREVN): {
601|      uint16_t level = *pc++;
602|      uint16_t v = *pc++;
603|      jv* var = frame_local_var(jq, v, level);
604|      jv_free(*var);
605|      *var = jv_null();
606|      goto do_backtrack;
607|      break;
608|    }
609|
610|    case STORE_GLOBAL: {
611|      // Get the constant
612|      jv val = jv_array_get(jv_copy(frame_current(jq)->bc->constants), *pc++);
613|      assert(jv_is_valid(val));
614|
615|      // Store the var
616|      uint16_t level = *pc++;
617|      uint16_t v = *pc++;
618|      jv* var = frame_local_var(jq, v, level);
619|      if (jq->debug_trace_enabled) {
620|        printf("V%d = ", v);
621|        jv_dump(jv_copy(val), 0);
622|        printf(" (%d)\n", jv_get_refcnt(val));
623|      }
624|      jv_free(*var);
625|      *var = val;
626|      break;
627|    }
