629|    case PATH_BEGIN: {
630|      jv v = stack_pop(jq);
631|      stack_push(jq, jq->path);
632|
633|      stack_save(jq, pc - 1, stack_get_pos(jq));
634|
635|      stack_push(jq, jv_number(jq->subexp_nest));
636|      stack_push(jq, jq->value_at_path);
637|      stack_push(jq, jv_copy(v));
638|
639|      jq->path = jv_array();
640|      jq->value_at_path = v; // next INDEX operation must index into v
