644|
645|    case PATH_END: {
646|      jv v = stack_pop(jq);
647|      // detect invalid path expression like path(.a | reverse)
648|      if (!path_intact(jq, jv_copy(v))) {
649|        char errbuf[30];
650|        jv msg = jv_string_fmt(
