655|      }
656|      jv_free(v); // discard value, only keep path
657|
658|      jv old_value_at_path = stack_pop(jq);
659|      int old_subexp_nest = (int)jv_number_value(stack_pop(jq));
660|
661|      jv path = jq->path;
662|      jq->path = stack_pop(jq);
663|
664|      struct stack_pos spos = stack_get_pos(jq);
665|      stack_push(jq, jv_copy(path));
666|      stack_save(jq, pc - 1, spos);
667|
668|      stack_push(jq, path);
669|      jq->subexp_nest = old_subexp_nest;
670|      jv_free(jq->value_at_path);
