712|
713|    case JUMP: {
714|      uint16_t offset = *pc++;
715|      pc += offset;
716|      break;
717|    }
718|
719|    case JUMP_F: {
720|      uint16_t offset = *pc++;
721|      jv t = stack_pop(jq);
722|      jv_kind kind = jv_get_kind(t);
723|      if (kind == JV_KIND_FALSE || kind == JV_KIND_NULL) {
