729|
730|    case EACH:
731|    case EACH_OPT: {
732|      jv container = stack_pop(jq);
733|      // detect invalid path expression like path(reverse | .[])
734|      if (!path_intact(jq, jv_copy(container))) {
735|        char errbuf[30];
736|        jv msg = jv_string_fmt(
737|            "Invalid path expression near attempt to iterate through %s",
