747|    case ON_BACKTRACK(EACH_OPT): {
748|      int idx = jv_number_value(stack_pop(jq));
749|      jv container = stack_pop(jq);
750|
751|      int keep_going, is_last = 0;
752|      jv key, value;
753|      if (jv_get_kind(container) == JV_KIND_ARRAY) {
754|        if (opcode == EACH || opcode == EACH_OPT) idx = 0;
755|        else idx = idx + 1;
756|        int len = jv_array_length(jv_copy(container));
757|        keep_going = idx < len;
758|        is_last = idx == len - 1;
759|        if (keep_going) {
760|          key = jv_number(idx);
761|          value = jv_array_get(jv_copy(container), idx);
762|        }
763|      } else if (jv_get_kind(container) == JV_KIND_OBJECT) {
764|        if (opcode == EACH || opcode == EACH_OPT) idx = jv_object_iter(container);
765|        else idx = jv_object_iter_next(container, idx);
766|        keep_going = jv_object_iter_valid(container, idx);
767|        if (keep_going) {
768|          key = jv_object_iter_key(container, idx);
769|          value = jv_object_iter_value(container, idx);
770|        }
771|      } else {
772|        assert(opcode == EACH || opcode == EACH_OPT);
773|        if (opcode == EACH) {
774|          char errbuf[15];
775|          set_error(jq,
776|                    jv_invalid_with_msg(jv_string_fmt("Cannot iterate over %s (%s)",
777|                                                      jv_kind_name(jv_get_kind(container)),
778|                                                      jv_dump_string_trunc(jv_copy(container), errbuf, sizeof(errbuf)))));
779|        }
780|        keep_going = 0;
781|      }
782|
783|      if (!keep_going || raising) {
784|        if (keep_going) {
785|          jv_free(key);
786|          jv_free(value);
787|        }
788|        jv_free(container);
789|        goto do_backtrack;
790|      } else if (is_last) {
791|        // we don't need to make a backtrack point
792|        jv_free(container);
793|        path_append(jq, key, jv_copy(value));
794|        stack_push(jq, value);
795|      } else {
796|        struct stack_pos spos = stack_get_pos(jq);
797|        stack_push(jq, container);
798|        stack_push(jq, jv_number(idx));
799|        stack_save(jq, pc - 1, spos);
800|        path_append(jq, key, jv_copy(value));
801|        stack_push(jq, value);
802|      }
803|      break;
804|    }
805|
806|    do_backtrack:
807|    case BACKTRACK: {
808|      pc = stack_restore(jq);
809|      if (!pc) {
810|        if (!jv_is_valid(jq->error)) {
811|          jv error = jq->error;
812|          jq->error = jv_null();
813|          return error;
814|        }
815|        return jv_invalid();
816|      }
817|      backtracking = 1;
818|      break;
819|    }
820|
821|    case TRY_BEGIN:
822|      stack_save(jq, pc - 1, stack_get_pos(jq));
823|      pc++; // skip handler offset this time
824|      break;
825|
826|    case TRY_END:
827|      stack_save(jq, pc - 1, stack_get_pos(jq));
828|      break;
829|
830|    case ON_BACKTRACK(TRY_BEGIN): {
831|      if (!raising) {
832|        /*
833|         * `try EXP ...` -- EXP backtracked (e.g., EXP was `empty`), so we
834|         * backtrack more:
835|         */
836|        jv_free(stack_pop(jq));
837|        goto do_backtrack;
838|      }
839|
840|      /*
841|       * Else `(try EXP ... ) | EXP2` raised an error.
842|       *
843|       * If the error was wrapped in another error, then that means EXP2 raised
844|       * the error.  We unwrap it and re-raise it as it wasn't raised by EXP.
845|       *
846|       * See commentary in gen_try().
847|       */
848|      jv e = jv_invalid_get_msg(jv_copy(jq->error));
849|      if (!jv_is_valid(e) && jv_invalid_has_msg(jv_copy(e))) {
850|        set_error(jq, e);
851|        goto do_backtrack;
852|      }
853|      jv_free(e);
854|
855|      /*
856|       * Else we caught an error containing a non-error value, so we jump to
857|       * the handler.
858|       *
859|       * See commentary in gen_try().
860|       */
861|      uint16_t offset = *pc++;
862|      jv_free(stack_pop(jq)); // free the input
863|      stack_push(jq, jv_invalid_get_msg(jq->error));  // push the error's message
864|      jq->error = jv_null();
865|      pc += offset;
866|      break;
867|    }
868|    case ON_BACKTRACK(TRY_END):
869|      // Wrap the error so the matching TRY_BEGIN doesn't catch it
870|      if (raising)
871|        set_error(jq, jv_invalid_with_msg(jv_copy(jq->error)));
872|      goto do_backtrack;
873|
874|    case DESTRUCTURE_ALT:
875|    case FORK: {
876|      stack_save(jq, pc - 1, stack_get_pos(jq));
877|      pc++; // skip offset this time
878|      break;
879|    }
880|
881|    case ON_BACKTRACK(DESTRUCTURE_ALT): {
882|      if (jv_is_valid(jq->error)) {
883|        // `try EXP ...` backtracked here (no value, `empty`), so we backtrack more
884|        jv_free(stack_pop(jq));
885|        goto do_backtrack;
886|      }
887|      // `try EXP ...` exception caught in EXP
888|      // DESTRUCTURE_ALT doesn't want the error message on the stack,
889|      // as we would just want to throw it away anyway.
890|      if (opcode != ON_BACKTRACK(DESTRUCTURE_ALT)) {
891|        jv_free(stack_pop(jq)); // free the input
892|        stack_push(jq, jv_invalid_get_msg(jq->error));  // push the error's message
893|      } else {
894|        jv_free(jq->error);
895|      }
896|      jq->error = jv_null();
897|      uint16_t offset = *pc++;
898|      pc += offset;
899|      break;
900|    }
901|    case ON_BACKTRACK(FORK): {
902|      if (raising) goto do_backtrack;
903|      uint16_t offset = *pc++;
904|      pc += offset;
905|      break;
906|    }
907|
908|    case CALL_BUILTIN: {
909|      int nargs = *pc++;
910|      struct cfunction* function = &frame_current(jq)->bc->globals->cfunctions[*pc++];
911|      jv in[MAX_CFUNCTION_ARGS];
912|      for (int i = 0; i < nargs; ++i)
913|        in[i] = stack_pop(jq);
914|
915|      jv top;
916|      switch (function->nargs) {
917|      case 1: top = function->fptr.a1(jq, in[0]); break;
918|      case 2: top = function->fptr.a2(jq, in[0], in[1]); break;
919|      case 3: top = function->fptr.a3(jq, in[0], in[1], in[2]); break;
920|      case 4: top = function->fptr.a4(jq, in[0], in[1], in[2], in[3]); break;
921|      default: assert(0 && "Invalid number of arguments");
922|      }
923|
924|      if (!jv_is_valid(top)) {
925|        if (jv_invalid_has_msg(jv_copy(top)))
926|          set_error(jq, top);
927|        goto do_backtrack;
928|      }
929|
930|      stack_push(jq, top);
931|      break;
932|    }
933|
934|    case TAIL_CALL_JQ:
935|    case CALL_JQ: {
936|      /*
937|       * Bytecode layout here:
938|       *
939|       *  CALL_JQ
940|       *  <nclosures>                       (i.e., number of call arguments)
941|       *  <callee closure>                  (what we're calling)
942|       *  <nclosures' worth of closures>    (frame reference + code pointer)
943|       *
944|       *  <next instruction (to return to)>
945|       *
946|       * Each closure consists of two uint16_t values: a "level"
947|       * identifying the frame to be closed over, and an index.
948|       *
949|       * The level is a relative number of call frames reachable from
950|       * the currently one; 0 -> current frame, 1 -> previous frame, and
951|       * so on.
952|       *
953|       * The index is either an index of the closed frame's subfunctions
954|       * or of the closed frame's parameter closures.  If the latter,
955|       * that closure will be passed, else the closed frame's pointer
956|       * and the subfunction's code will form the closure to be passed.
957|       *
958|       * See make_closure() for more information.
959|       */
960|      jv input = stack_pop(jq);
961|      uint16_t nclosures = *pc++;
962|      uint16_t* retaddr = pc + 2 + nclosures*2;
963|      stack_ptr retdata = jq->stk_top;
964|      struct frame* new_frame;
965|      struct closure cl = make_closure(jq, pc);
966|      if (opcode == TAIL_CALL_JQ) {
967|        retaddr = frame_current(jq)->retaddr;
968|        retdata = frame_current(jq)->retdata;
969|        frame_pop(jq);
970|      }
971|      new_frame = frame_push(jq, cl, pc + 2, nclosures);
972|      new_frame->retdata = retdata;
973|      new_frame->retaddr = retaddr;
974|      pc = new_frame->bc->code;
975|      stack_push(jq, input);
976|      break;
977|    }
978|
979|    case RET: {
980|      jv value = stack_pop(jq);
981|      assert(jq->stk_top == frame_current(jq)->retdata);
982|      uint16_t* retaddr = frame_current(jq)->retaddr;
983|      if (retaddr) {
984|        // function return
985|        pc = retaddr;
986|        frame_pop(jq);
987|      } else {
988|        // top-level return, yielding value
989|        struct stack_pos spos = stack_get_pos(jq);
990|        stack_push(jq, jv_null());
991|        stack_save(jq, pc - 1, spos);
992|        return value;
993|      }
994|      stack_push(jq, value);
995|      break;
996|    }
997|    case ON_BACKTRACK(RET): {
998|      // resumed after top-level return
999|      goto do_backtrack;
1000|    }
1001|    }
1002|  }
1003|}

