617|static const char* jvp_literal_number_literal(jv n) {
618|  assert(JVP_HAS_FLAGS(n, JVP_FLAGS_NUMBER_LITERAL));
619|  decNumber *pdec = jvp_dec_number_ptr(n);
620|  jvp_literal_number* plit = jvp_literal_number_ptr(n);
621|
622|  if (decNumberIsNaN(pdec)) {
623|    return "null";
624|  }
625|
626|  if (decNumberIsInfinite(pdec)) {
627|    // We cannot preserve the literal data of numbers outside the limited
628|    // range of exponent. Since `decNumberToString` returns "Infinity"
629|    // (or "-Infinity"), and to reduce stack allocations as possible, we
630|    // normalize infinities in the callers instead of printing the maximum
631|    // (or minimum) double here.
632|    return NULL;
633|  }
